/*
-----------------------------------------------

Responsive Blogger Template
Nome: Urbaine
Versão: 1.0
Design + Código: Gabriela Melo
URL 1: http://www.oaess.com.br
URL 2: http://shop.gabrielamelo.com.br
Etsy Shop: https://www.etsy.com/shop/shopgabrielamelo
Data: Julho 2017

----------------------------------------------- */

/*! normalize.css v6.0.0 | MIT License | github.com/necolas/normalize.css */
button,hr,input{overflow:visible}audio,canvas,progress,video{display:inline-block}progress,sub,sup{vertical-align:baseline}[type=checkbox],[type=radio],legend{box-sizing:border-box;padding:0}html{line-height:1.15;-ms-text-size-adjust:100%;-webkit-text-size-adjust:100%}article,aside,details,figcaption,figure,footer,header,main,menu,nav,section{display:block}h1{font-size:2em;margin:.67em 0}figure{margin:1em 40px}hr{box-sizing:content-box;height:0}code,kbd,pre,samp{font-family:monospace,monospace;font-size:1em}a{background-color:transparent;-webkit-text-decoration-skip:objects}abbr[title]{border-bottom:none;text-decoration:underline;text-decoration:underline dotted}b,strong{font-weight:bolder}dfn{font-style:italic}mark{background-color:#ff0;color:#000}small{font-size:80%}sub,sup{font-size:75%;line-height:0;position:relative}sub{bottom:-.25em}sup{top:-.5em}audio:not([controls]){display:none;height:0}img{border-style:none}svg:not(:root){overflow:hidden}button,input,optgroup,select,textarea{margin:0}button,select{text-transform:none}[type=reset],[type=submit],button,html [type=button]{-webkit-appearance:button}[type=button]::-moz-focus-inner,[type=reset]::-moz-focus-inner,[type=submit]::-moz-focus-inner,button::-moz-focus-inner{border-style:none;padding:0}[type=button]:-moz-focusring,[type=reset]:-moz-focusring,[type=submit]:-moz-focusring,button:-moz-focusring{outline:ButtonText dotted 1px}legend{color:inherit;display:table;max-width:100%;white-space:normal}textarea{overflow:auto}[type=number]::-webkit-inner-spin-button,[type=number]::-webkit-outer-spin-button{height:auto}[type=search]{-webkit-appearance:textfield;outline-offset:-2px}[type=search]::-webkit-search-cancel-button,[type=search]::-webkit-search-decoration{-webkit-appearance:none}::-webkit-file-upload-button{-webkit-appearance:button;font:inherit}summary{display:list-item}[hidden],template{display:none}
.clearfix:after {content:"";display:block;clear:both;}


/*--------------------------------------------
*
* 1. POR FAVOR, NÃO EDITE O CÓDIGO ACIMA ⇑
*
* 2. Não é necessário adicionar um CSS RESET,
*    pois o template já tem Normalize.
*
----------------------------------------------*/


#Navbar1, #Attribution1, h1 p, .feed-links, a.home-link {
    display: none;
}

html {
	-webkit-box-sizing: border-box;
    -moz-box-sizing: border-box;
    box-sizing: border-box;
	font-size: 62.5%;
}

body {
	background: #fff;
	font-family: "Work Sans", sans-serif;
	font-size: 1.4em;
	font-weight: normal;
	word-wrap: break-word;
}

img {
	max-width: 100%;
	height: auto;
}

a {
	color: #828282;
	text-decoration: none;
}

a:hover {
	color: #000;
}

:focus {
    outline: 0;
}

::-webkit-scrollbar {
    background: #ccc; 
    height:10px;
    width:10px; 
}

::-webkit-scrollbar-thumb:vertical {
    background: #333;
    height:50px;
}

::-webkit-scrollbar-thumb:horizontal {
    background-color:#333;
    height:10px;
}

::-moz-selection {
    background: #fbfbfb;
    color: #555;
}

::selection {
    background: #fbfbfb;
    color: #555; 
}

.status-msg-wrap {
    background: none;
	font-size: 80%;
	letter-spacing: 2px;
	padding: 1em;
    width: 100%;
}

.status-msg-border { 
    border: 0;
} 

.status-msg-body {
    background: #fff;
    text-transform: uppercase;
}

em, i {
	font-family: serif;
	font-style: italic;
} 


/*--------------------------------
* Menu
----------------------------------*/

#PageList100 ul { 
	display: none;
}

.open-pages {
	cursor: pointer;
	font-size: 90%;
	letter-spacing: 3px;
	padding: 3em .5em .5em .5em;
	text-align: center;
	text-transform: uppercase;
}

.btn-close {
	background: none;
	border: 0;
	color: #222;
	cursor: pointer;
	font-size: 150%;
	margin: 1.3em 3em 0 0;
	position: absolute;
	right: 2.5%;
	top: 2%;
}

ul.gbml-modal {
	background: #fff;
	bottom: 0;
	display: -moz-box;
	display: -ms-flexbox;
	display: -webkit-flex; 
	display: -webkit-box;
	display: flex;
	flex-direction: column;
	font-family: trocchi, serif;
	font-size: 110%;
	justify-content: center;
	left: 0;
	list-style-type: none;
	height: 100vh;
	margin: 0;
	padding: 0;
	position: fixed;
	right: 0;
    text-align: center;
	text-transform: lowercase;
	top: 0;
}

ul.gbml-modal li {
	clear: both;
	padding: .5em;
	width: 100%;
}

ul.gbml-modal li a {
	color: #222;
}

ul.gbml-modal li a:after {
	background: #ccc;
	content:"";
	display: block;
	height: 1px;
	margin: 0 auto;
	margin-top: 1.5em;
	width: 30px;
}



/*--------------------------------
* Colunas
----------------------------------*/

.section {
	margin: 0;
}

@media screen and (min-width:50em) {
	.header-wrap, .post-destacado, .container {
		margin: 0 auto;
		max-width: 1200px;
		width: 85%;
	}
}

.main-wrap {
    border-top: 1px solid #000;
}

.sidebar-wrap {
	margin: 0 auto;
	max-width: 400px;
	padding: 0;
	width: 100%;
}

@media screen and (min-width:61em) {
	.main-wrap {
		float: left;
		width: 67%;
	}

	.sidebar-wrap {
		float: right;
		width: 29%;
	}
}


/*--------------------------------
* Header
----------------------------------*/

.header-wrap {
    margin: 3em auto 6em;
}

.header {
	letter-spacing: 2px;
	padding: 2em 0 2em;
}

#Header1_headerimg {
	margin-left: auto;
	margin-right: auto;
}

#Header1 h1 {
	color: #222;
	font-family: 'work sans';
	font-size: 2.5em;
	font-weight: normal;
    letter-spacing: 5px;
	margin-bottom: 1em;
	text-decoration: none;
	text-align: center;
	text-transform: uppercase; 
	width: 100%;
	z-index: 1000;
}

#Header1 a, #Header1 a {
	color: #222;
}

h1.title {
	margin-top: 0;
}


/*--------------------------------
* Post Destacado
----------------------------------*/

.post-destacado {
	margin-bottom: 8em;
}

#FeaturedPost1 .post-summary .image {
	display: none;
	width: 100%;
}

#FeaturedPost1 .fav-title-snippet {
	margin: 0 auto;
	text-align: center;
	width: 80%;
}

#FeaturedPost1 .fav-title-snippet h3, #FeaturedPost1 .fav-title-snippet h3 a {
	color: #222;
	font-family: trocchi, sans-serif;
	font-size: 120%;
	font-weight: normal;
	letter-spacing: -1px;
	padding-top: 2em;
}	

#FeaturedPost1 .fav-title-snippet p {
	font-size: 80%;
}

#FeaturedPost1 .fav-title-snippet .fav-borda {
	background: #222;
	clear: both;
	display: block;
	height: 1px;
	margin: 0 auto;
	margin-top: 1.em;
	width: 40%;
}

@media screen and (min-width:50em) {
	#FeaturedPost1 {
		margin: 0;
	}

	#FeaturedPost1 .fav-post .fav-post-summary img {
		display: inline;
	}

	#FeaturedPost1 .fav-post-summary {
		padding: 0;
	}

	#FeaturedPost1 .fav-post-summary .image {
		display: none;
		width: 50%;
	}

	#FeaturedPost1 .fav-title-snippet {
		position: absolute;
		top: 30%;
		bottom: 0;
		right: 5%;
		text-align: right;
		width: 65%;
	}

	#FeaturedPost1 .fav-title-snippet h3, #FeaturedPost1 .fav-title-snippet h3 a {
		font-size: 130%;
	}

	#FeaturedPost1 .fav-title-snippet h3 { 
		float: right; 
		width: 55%; 
	}

	#FeaturedPost1 .fav-title-snippet p { 
		clear: both;
		float: right;
		width: 45%;
	}

	#FeaturedPost1 .fav-title-snippet .fav-borda {
		clear: both;
		margin: 0;
		margin-top: 1.2em;
		width: 100%;
	} 
}	

@media screen and (min-width:64em) {

	#FeaturedPost1 .fav-title-snippet h3, #FeaturedPost1 .fav-title-snippet h3 a {
		font-size: 150%;
	}

	#FeaturedPost1 .fav-title-snippet {
		top: 45%;
	}
}



/*--------------------------------
* Posts
----------------------------------*/

.post {
	line-height: 1.9em;
	margin-bottom: 7em;
    padding-top: 1em;
}

.post-header {
	text-align: center;
}

.date-author {
	display: inline-block;
	font-size: 80%;
	letter-spacing: 3px;
	text-transform: uppercase;
}

.date-header:after {
	content: "-";
	padding: 0 .3em 0 .6em;
}

.post-title {
	color: #222;
	font-family: trocchi, serif;
	font-size: 1.8em;
	font-weight: normal;
	padding: .4em 0;
	text-transform: lowercase;
}

.post-title a {
	color: #222;
}

.post-title a:hover {
	color: #555;
}

.post-title::after {
	background: #222;
	content:"";
	display: block;
	left: 50%;
	height: 100%;
	padding: 1em 0;
	position: relative;
	top: .7em;
	width: 1px;
}

.post-body a {
	border-bottom: 2px solid #ccc;
	padding-bottom: .1em;
}

.post-body .separator a {
	border: 0;
	margin: 0!important;
}

.post-body a.img,
.post-body .tr-caption-container,
.post-body table, .post-body tbody,
.post-body td, .post-body tr,
.post-thumb a,
.post-body td a {
	border: 0;
}

.post-summary {
	margin: 0 auto;
	padding: 1em 0;
	text-align: justify;
	width: 75%;
}

.read-more {
	font-family: trocchi, serif;
	margin-top: 1.4em;
	text-align: center;
	text-transform: lowercase;
}

.read-more a {
	border: 1px solid #222;
	color: #222;
	letter-spacing: 1px;
	margin: 0 auto;
	max-width: 300px;
	padding: 1em 3em;
	text-align: center;
}

.read-more a:hover {
	background: #fbfbfb;
}

.post-body h2, h3, h4 {
	font-family: trocchi, serif;
	font-weight: normal;
	padding: .5em 0;
}

.post-body blockquote.tr_bq {
	border: 1px solid #828282;
	border-left: 2px solid;
	color: #555;
	font-family: trocchi, serif;
	font-size: 90%;
	font-weight: normal;
	margin: 0;
	padding: 2em;
}

.img-left {
	padding: 1em 1em 1em 0!important;
}

.img-right {
	padding: 1em 0 1em 1em!important;
}

@media screen and (max-width:37.5em) {
	.img-left, .img-left img, .img-right, .img-right img {
		max-width: 100% !important; 
		padding: 1em 0 1em 0 !important; 
		width: 600px !important;
	}
}

.post-share-buttons.google-inline-block {
	max-width: 100%;
}


/*--------------------------------
* Comentários
----------------------------------*/

.comments {
	font-size: 85%;
	margin-left: auto;
	margin-right: auto;
	padding-bottom: 5em;
	width: 90%;
}

.comments h4 {
	font-family: trocchi, serif;
	font-size: 130%;
	font-weight: normal;
	text-align: center;
	text-transform: lowercase;
}

.comments .comment-block {
	margin-left: 0;
}

.comments .comment-header {
	border-bottom: 1px solid #f1f1f1;
	font-family: trocchi, serif;
	font-size: 110%;
}
.comments .user .blog-author {
	font-weight: 400;
	text-transform: lowercase;
}

.comments .comment-header a {
	color: #222;
}

.comments .comment-header .datetime {
	font-family: "work sans", sans-serif;
	font-size: 85%;
	text-transform: uppercase;
}

.comments .comment-content {
	padding: 1em 0;
}

.comments .comment-actions {
	display: block;
	font-size: 90%;
	text-transform: uppercase;
}

.comments .comment-actions a {
	margin-right: 2em;
}

.comments .avatar-image-container {
	display: none;
}

#comment-editor {
  height: 280px !important;
  width: 100% !important;
}

#comment-post-message {
  text-align: center;
}

.comment-form {
  max-width: 100%;
  width: 100%;
}



/*--------------------------------
* Paginação
----------------------------------*/

#blog-pager {
	clear: both;
	font-size: 85%;
	letter-spacing: 1px;
	margin-bottom: 7em;
	text-transform: uppercase;
}

#blog-pager {
	border-bottom: 1px solid #f1f1f1;
	padding-bottom: .4em;
}


/*--------------------------------
* Sidebar
----------------------------------*/

.sidebar {
    line-height: 1.5em;
	padding: 0;
}

.sidebar .widget {
    margin: 0 0 3em;
}

.sidebar .widget-content {
	border: 1px solid #f1f1f1;
	padding: 1em;
}

.sidebar h2 {
	font-family: trocchi, serif;
	font-size: 90%;
	font-weight: normal;
	padding: 1em 0;
	text-align: center;
	text-transform: lowercase;
}

.sidebar ul {
    list-style:none;
    margin:0 0 0;
    padding:0 0 0;
}

.sidebar li {
    margin:0;
    padding: 0 0 .25em 15px;
    line-height:1.5em;
}


/* Perfil
---------- */

#Image100 h3, #HTML99 h2 {
	display: none;
}

#Image100.widget {
	margin-bottom: 0;
}

#Image100 .widget-content,
#HTML99 .widget-content,
#Label100 .widget-content {
	border: 0;
	padding: 0;
}

#Image100_img {
	height: auto;
	width: 100%;
}

#Image100 .caption {
	display: block;
	font-size: 95%;
	letter-spacing: 2px;
	padding: 1em;
	text-align: center;
	text-transform: uppercase;
}

#HTML99 {
	border: 1px solid #333;
	font-size: 85%;
	padding: 1.5em 2em;
	text-align: justify;
}


/* Busca
---------- */

#HTML90 h2 {
	display: none;
}

#HTML90 .widget-content {
	padding: 2em;
	text-align: center;
}

.custom-search-form3 {
	padding-bottom: .3em;
}

.custom-search-box3 {
	border: 0;
	border-bottom: 1px solid;
	font-family: 'work sans', sans-serif;
	font-size: 80%;
	letter-spacing: 1px;
	padding: .5em 0;
	text-align: center;
	text-transform: uppercase;
	width: 100%;
}


/* Marcadores
-------------- */

#Label100 h2 {
	font-family: 'work sans', sans-serif;
	letter-spacing: 1px;
	text-align: left;
	text-transform: uppercase;
}

#Label100 .list-label-widget-content {
	font-size: 80%;
	letter-spacing: 1px;
	text-transform: uppercase;
}

#Label100 .list-label-widget-content ul li a:before {
	color: #f1f1f1;
	content: "---------------";
	letter-spacing: -2px;
	padding: 0 .5em;
}

#Label100 .list-label-widget-content ul li {
	padding: .5em 0;
}


/* Arquivo
------------ */

.BlogArchive ul li {
	font-size: 90%;
	letter-spacing: 1px;
	padding-left: 0;
	text-align: center;
	text-transform: uppercase;
}


/*--------------------------------
* Posts Populares
----------------------------------*/

.popularposts-wrap {
	background: #f5f6f6;
	margin-top: 4em;
	padding: 2em 0;
	width: 100%;
}

.popular-posts {
	margin: 0 auto;
	max-width: 1200px;
}

.PopularPosts h2, .PopularPosts .item-snippet, .PopularPosts ul li:nth-child(n+5) {
	display: none;
}

.PopularPosts ul, .PopularPosts .item-thumbnail a img {
	list-style-type: none;
	padding: 0;
}

.PopularPosts {
	counter-reset: contarpp;
}

.PopularPosts ul li:before {
	color: #fff;
	content: counter(contarpp, decimal);
	counter-increment: contarpp;
	font-family: trocchi, serif;
	font-size: 4em;
	margin: -.455em 0 0;
	overflow: hidden;
	position: absolute;
	z-index: 500;
}

.PopularPosts .item-content {
	position: relative;
}

.PopularPosts .item-thumbnail, 
.PopularPosts .item-thumbnail img,
.PopularPosts .item-thumbnail a img {
	float: none;
	margin: 0;
	padding: 0;
	width: 100%;
}

.PopularPosts .item-thumbnail {
	width: 100%;
}

.PopularPosts .item-thumbnail:hover {
	filter:alpha(opacity=70);
	-moz-opacity:0.7;
	-khtml-opacity:0.7;
	opacity:0.7;
}

.PopularPosts .item-title {
	-webkit-box-sizing: border-box;
    -moz-box-sizing: border-box;
    box-sizing: border-box;
	bottom: -.5em;
	background: #fff;
	font-family: trocchi, serif;
	font-size: 80%;
	font-weight: normal;
	letter-spacing: 1px;
	margin: 0 auto;
	padding: 2em;
	right: 2%;
	text-align: center;
	position: absolute;
	width: 80%;
	z-index: 500;
}

.PopularPosts .item-title a {
	color: #222;
}

.PopularPosts .item-title a:hover {
	color: #828282;
}

@media screen and (min-width: 31em) {
	.PopularPosts ul li {
		float: left;
		width: 50%;
	}
}

@media screen and (min-width: 56em) {
	.PopularPosts ul li {
		width: 25%;
	}
}



/*--------------------------------
* Footer
----------------------------------*/

.FollowByEmail {
	margin: 0 auto;
	max-width: 700px;
	padding: 3em 0;
	width: 80%;
}

@media screen and (min-width: 64em) {
	.FollowByEmail {
		width: 50%;
	}
}

.FollowByEmail h2 {
	color: #828282;
	font-family: trocchi, serif;
	font-size: 80%;
	font-weight: normal;
	padding-bottom: .4em;
	text-align: center;
	text-transform: lowercase;
}

.FollowByEmail .follow-by-email-inner .follow-by-email-address {
	border-left: 0;
	border-right: 0;
	border-top: 0;
	border: 1px solid #828282;
	color: #828282;
	font-family: 'work sans', sans-serif;
	font-size: 70%;
	letter-spacing: 1px;
	padding: .5em;
	text-align: center;
	text-transform: uppercase;
	width: 100%;
}

.FollowByEmail .follow-by-email-inner .follow-by-email-submit {
	background: #555;
	border: 0;
	color: #fbfbfb;
	cursor: pointer;
	margin: 0;
	padding: 0;
	width: 45px;
	height: 35px;
}

.FollowByEmail .follow-by-email-inner .follow-by-email-submit:hover {
	background: #828282;
}

.links-footer {
	display: block;
	font-family: 'work sans', sans-serif;
	font-size: 72%;
	letter-spacing: 1px;
	line-height: 2em;
	padding-bottom: 1em;
	text-align: center;
	text-transform: uppercase;
}

@media screen and (min-width: 40em) {
	.blogname-footer, .gbml-credits {
		display: inline;
	}
}

.backtotop {
	background: #f1f1f1;
	color: #828282;
	font-size: 250%;
	margin: 0 auto;
	text-align: center;
	width: 50px;
}


/* end css */

b:if.script:
//
jQuery( document ).ready(function( $ ) {
  var width  = 960;
  var height = 1100;
  $('#FeaturedPost1').find('img').each(function(n, image){
    var image = $(image);
    image.attr({src : image.attr('src').replace(/s\B\d{2,4}/,'w' + width + '-h' +  height + '-c')});
    image.attr('width', "100%");
    image.attr('height', "auto");
    image[0].style.display = "block";
  });
});
